Stap 5. Gemiddelde dagproductie

We willen een grafiek met de gemiddelde melkproductie per dag, we moeten dit berekenen.
We passen de server functie hiervoor aan: vervang in app.R alleen de server functie door de code hieronder. Het ui object blijft hetzelfde
Het begint er nu op te lijken


code.R

server = function(input, output, session) {
  dt &lt;- reactive({
    data |&gt;
      filter(productie &gt; 0, !is.na(datum)) |&gt;
      group_by(datum) |&gt;
      summarise(productie = mean(productie, na.rm = TRUE), .groups = "drop")
  })

  output$grafiek &lt;- renderPlot({
    ggplot(dt(), aes(x = datum, y = productie)) +
      geom_line(linewidth = 0.8, alpha = 0.8) +
      geom_point(size = 1.5) +
      labs(
        title = 'Melkproductie',
        x = "Datum",
        y = "Productie"
      )
  })
}

shinyApp(ui, server)

Stap 7: Tabel

We willen ook een tabel met daarin de geselecteerde data; hiervoor gebruiken we pakket DT
De tabel wordt in de output lijst in server gezet en we geven hem vervolgens weer in ui
De selecties laten we voorlopig voor wat ze zijn


code.R

ui = page_navbar(
  title = 'Analyse productiedata',
  sidebar = sidebar(inputs),
  nav_panel(
    title = "Dashboard",
    card(
      full_screen = TRUE,
      card_header("Kenmerken over de tijd"),
      card_body(plotOutput("grafiek"))
    ),
    card(
      full_screen = TRUE,
      card_header("Tabel van de gegevens"),
      card_body(fillable = TRUE, DTOutput("tabel"))
    )
  )
)

server = function(input, output, session) {
  dt &lt;- reactive({
    data |&gt;
      filter(
        productie &gt; 0,
        !is.na(datum),
        lactatie &gt;= input$lacts[1],
        lactatie &lt;= input$lacts[2],
        dim &gt;= input$dims[1],
        dim &lt;= input$dims[2]
      )
  })

  output$grafiek &lt;- renderPlot({
    req(dt())

    dt() |&gt;
      group_by(datum) |&gt;
      summarise(productie = mean(productie, na.rm = TRUE), .groups = "drop") |&gt;
      ggplot(aes(x = datum, y = productie)) +
      geom_line(linewidth = 0.8, alpha = 0.8) +
      geom_point(size = 1.5) +
      labs(
        title = 'Melkproductie',
        x = "Datum",
        y = "Productie"
      )
  })

  output$tabel &lt;- renderDT({
    req(dt())

    datatable(
      dt() |&gt;
        arrange(id, datum)
    )
  })
}

shinyApp(ui, server)
